module fsm #(
    parameter s0 = 3'b000,
    parameter s1 = 3'b001,
    parameter s2 = 3'b010,
    parameter s3 = 3'b011,
    parameter s4 = 3'b100,
    parameter s5 = 3'b101
) (
    input IN,
    output reg MATCH,
    input CLK,
    input RST
);

reg [2:0] state, next_state;

parameter IDLE = s0;
parameter DETECT_1 = s1;
parameter DETECT_0 = s2;
parameter DETECT_00 = s3;
parameter DETECT_11 = s4;
parameter DETECT_110 = s5;

always @(posedge CLK or posedge RST) begin
    if (RST) state <= IDLE; else state <= next_state;
end

always @(*) begin
    next_state = state;
    MATCH = 0;

    case (state)
        IDLE: begin
            if (IN == 1)
                next_state = DETECT_1;
        end
        DETECT_1: begin
            if (IN == 0)
                next_state = DETECT_0;
        end
        DETECT_0: begin
            if (IN == 0)
                next_state = DETECT_00;
        end
        DETECT_00: begin
            if (IN == 1)
                next_state = DETECT_11;
        end
        DETECT_11: begin
            if (IN == 1)
                next_state = DETECT_110;
            MATCH = 1;
        end
        DETECT_110: begin
            if (IN == 0)
                next_state = DETECT_00;
        end
        default: begin
            next_state = IDLE;
        end
    endcase
end

endmodule
